{"source":""""Visual finish bridge for the scene demo.

Candidate, unused module. Reuses the existing control.run_finish pipeline without
modifying controllers, sensors, or homing. Pure imports, no side effects.
"""

from __future__ import annotations

import json
import math
import os
from collections import deque


_PLACE_OPS = ("on", "in")
_TURN_OPS = ("turnon", "turnoff")


def build_context(capability, user_request):
    if not isinstance(capability, dict):
        raise ValueError("capability must be a dict")
    if not isinstance(user_request, str) or not user_request.strip():
        raise ValueError("user_request must be a non-empty string")
    goals = capability.get("goals")
    if not isinstance(goals, list) or len(goals) != 1:
        raise ValueError("capability must contain exactly one goal")
    goal = goals[0]
    if not isinstance(goal, dict):
        raise ValueError("goal must be a dict")
    operation = goal.get("operation")
    if not isinstance(operation, str):
        raise ValueError("goal.operation must be a string")
    operation = operation.strip()
    if operation in _PLACE_OPS:
        kind = "place"
    elif operation in _TURN_OPS:
        kind = "turn"
    else:
        raise ValueError("unsupported operation: %r" % (operation,))

    target = goal.get("target")
    destination = goal.get("destination")
    if target is None:
        raise ValueError("goal.target is required")
    if destination is None:
        raise ValueError("goal.destination is required")

    if kind == "place":
        semantics = (
            "place target onto destination support; keep the target on the "
            "support, then open the fingers and retreat away without disturbing it"
        )
    else:
        semantics = (
            "turn the target knob or switch to the requested state by rotating it; "
            "this is not opening a lid, and is not grasping the target again"
        )

    criteria = {
        "must_release": True,
        "must_stabilize": True,
        "must_clear": True,
        "must_preserve_target": True,
        "operation_semantics": semantics,
    }
    if kind == "turn":
        criteria["desired_state"] = "on" if operation == "turnon" else "off"

    return {
        "user_request": user_request,
        "current_subtask": {
            "operation": operation,
            "target": target,
            "destination": destination,
            "phase": "post_execution",
        },
        "criteria": criteria,
    }


class FinishMonitor:
    def __init__(self, env, reference, output_dir, context, guarded_step, on_action,
                 independent_ready, budget, client=None):
        import numpy as _np  # noqa: F401  (lazy, imported for availability check)
        from scene_demo.finish_v1 import vision as _vision  # noqa: F401
        from scene_demo.finish_v1.sensor import SensorPort as _SensorPort

        self.env = env
        self.reference = reference
        from pathlib import Path as _Path
        self.output_dir = _Path(output_dir)
        self.context = context
        self.guarded_step = guarded_step
        self.on_action = on_action
        self.independent_ready = independent_ready
        self.budget = int(budget)

        self.call_client = None
        self._client_explicit = client is not None
        if client is None:
            from scene_demo.llm import QwenClient as _QwenClient
            client = _QwenClient(max_calls=10)
        self.call_client = client

        self.port = _SensorPort(
            env, reference, self.output_dir / "sensors",
            step_callback=self._on_action,
        )
        # Guard this port instance's step only; do not touch env.step or control.
        self._orig_step = self.port.step
        self.port.step = lambda q, f=None: self.guarded_step(
            lambda: self._orig_step(q, f)
        )

        self.history = deque(maxlen=3)
        self.calls = 0
        self.prechecks = 0
        self.interval = max(25, int(math.ceil(self.budget / 5.0)))
        self.next_due = self.interval
        self.last_candidate = False
        self.terminal = None
        self.independent_streak = 0
        self.helper_counts = {"release": 0, "movement": 0, "confirm": 0, "home": 0}
        self._helper_actions = 0
        self._last_decision = None
        self._closed = False
        self._max_calls = 10
        self._max_prechecks = 5
        self._checks_path = self.output_dir / "checks.jsonl"
        self._finish = None

    # -- serialization helpers -------------------------------------------

    def _obs_key(self, obs):
        if not isinstance(obs, dict):
            return None
        ts = obs.get("timestamp")
        if ts is None:
            return None
        try:
            return float(ts)
        except (TypeError, ValueError):
            return None

    def _obs_frames(self, obs):
        if not isinstance(obs, dict):
            return []
        out = []
        for frame in obs.get("verification_frames") or []:
            out.append(frame)
        if not out:
            for frame in obs.get("frames") or []:
                out.append(frame)
        return out

    def _collect_observations(self, extra_observations):
        seen = set()
        merged = []

        def add(obs):
            key = self._obs_key(obs)
            if key is None or key in seen:
                return
            seen.add(key)
            merged.append(obs)

        for obs in list(self.history):
            add(obs)
        for obs in extra_observations or []:
            add(obs)
        try:
            fresh = self.port.capture()
            add(fresh)
        except Exception:
            pass
        return merged[-3:]

    def _obs_public(self, obs):
        out = []
        verification = obs.get("verification_frames") or []
        frames = verification if verification else (obs.get("frames") or [])
        for idx, frame in enumerate(frames[:6]):
            if not isinstance(frame, dict):
                continue
            out.append({
                "frame": idx,
                "view": frame.get("view"),
                "timestamp": obs.get("timestamp"),
                "rgb_path": frame.get("rgb_path"),
                "depth_path": frame.get("depth_path"),
            })
        return out

    def _obs_paths(self, obs):
        out = []
        verification = obs.get("verification_frames") or []
        frames = verification if verification else (obs.get("frames") or [])
        for frame in frames[:6]:
            if isinstance(frame, dict) and frame.get("rgb_path"):
                out.append(frame["rgb_path"])
        return out

    def _robot_public(self, robot):
        if not isinstance(robot, dict):
            return {
                "finger_qpos": None,
                "max_abs_arm_qvel": None,
                "arm_qpos": None,
                "stage": None,
            }
        arm_qvel = robot.get("arm_qvel")
        max_v = None
        if arm_qvel is not None:
            try:
                max_v = float(max(abs(float(x)) for x in arm_qvel))
            except (TypeError, ValueError):
                max_v = None
        stage = self.port.phase if self.port.phase is not None else "post_execution"
        return {
            "finger_qpos": robot.get("finger_qpos"),
            "max_abs_arm_qvel": max_v,
            "arm_qpos": robot.get("arm_qpos"),
            "stage": stage,
        }

    def _write_check(self, row):
        try:
            self.output_dir.mkdir(parents=True, exist_ok=True)
            with open(self._checks_path, "a") as fh:
                fh.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass

    # -- action callback --------------------------------------------------

    def _on_action(self, row):
        if isinstance(row, dict):
            phase = row.get("phase")
            if phase in self.helper_counts:
                self.helper_counts[phase] += 1
            self._helper_actions += 1
        try:
            ready = bool(self.independent_ready())
        except Exception:
            ready = False
        if ready:
            self.independent_streak += 1
        else:
            self.independent_streak = 0
        if self._helper_actions % 5 == 0:
            try:
                obs = self.port.capture()
                key = self._obs_key(obs)
                if key is not None and not any(
                    self._obs_key(h) == key for h in self.history
                ):
                    self.history.append(obs)
            except Exception:
                pass
        if self.on_action is not None:
            try:
                self.on_action(row)
            except Exception:
                pass

    # -- record / poll ----------------------------------------------------

    def record(self, step):
        if self.terminal is not None:
            return
        step = int(step)
        if step % 5 != 0:
            return
        try:
            obs = self.port.capture()
        except Exception:
            return
        key = self._obs_key(obs)
        if key is None:
            return
        if any(self._obs_key(h) == key for h in self.history):
            return
        self.history.append(obs)

    def _check(self, context, observations):
        merged = self._collect_observations(observations)
        frames = []
        for obs in merged:
            frames.extend(self._obs_public(obs))
        frames = frames[:6]
        paths = []
        seen_paths = set()
        for obs in merged:
            for path in self._obs_paths(obs):
                if path not in seen_paths:
                    seen_paths.add(path)
                    paths.append(path)

        robot = self.port.read_robot()
        ctx = {
            "user_request": self.context.get("user_request"),
            "current_subtask": self.context.get("current_subtask"),
            "criteria": self.context.get("criteria"),
            "sensor_frames": frames,
            "robot": self._robot_public(robot),
            "stage": self.port.phase if self.port.phase is not None else "post_execution",
        }

        if self.calls >= self._max_calls:
            raise RuntimeError("visual check call budget exhausted")

        self.guarded_step(lambda: None)
        self.calls += 1
        try:
            result = self.call_client.analyze(ctx, paths)
        except Exception:
            raise
        self.guarded_step(lambda: None)

        if not isinstance(result, dict):
            raise RuntimeError("analyze must return a dict")
        meta = result.get("meta") if isinstance(result.get("meta"), dict) else result
        raw = result.get("verdict", result.get("raw_verdict"))
        if raw is None and isinstance(meta, dict):
            raw = meta.get("verdict")
        if raw is None:
            raise RuntimeError("analyze result missing verdict")

        from scene_demo.finish_v1 import vision as _vision
        verdict = _vision.reconcile_verdict(ctx, raw, robot, self.reference)

        record = {
            "raw_verdict": raw,
            "verdict": verdict,
            "usage": result.get("usage"),
            "model": result.get("model"),
            "http_status": result.get("http_status"),
            "request_sha256": result.get("request_sha256"),
            "response_sha256": result.get("response_sha256"),
            "call_index": result.get("call_index", self.calls - 1),
            "frames": paths,
            "ctx": ctx,
            "robot": robot,
        }
        self._write_check(record)
        return verdict

    def _finish_outcome(self, ok, reason):
        self.terminal = {
            "ok": bool(ok),
            "reason": reason,
            "checks": self.calls,
        }
        if self._finish is not None:
            self.terminal["finish"] = self._finish
        return self.terminal

    def poll(self, step, candidate=False, force=False):
        if self.terminal is not None:
            return self.terminal
        step = int(step)
        self.last_candidate = bool(candidate)

        distinct = len({self._obs_key(h) for h in self.history if self._obs_key(h) is not None})
        first_candidate = bool(candidate) and not self.last_candidate
        due = step >= self.next_due
        can = distinct >= 2 and self.prechecks < self._max_prechecks and (due or candidate or force) and (distinct >= 2)
        if not can:
            return None
        if distinct < 2:
            return None

        from scene_demo.finish_v1 import vision as _vision

        self.next_due = step + self.interval
        self.prechecks += 1

        try:
            verdict = self._check(self.context, list(self.history))
        except Exception:
            self.close()
            raise

        try:
            decision = _vision.decide(self.context, verdict)
        except Exception:
            self.close()
            raise
        self._last_decision = decision

        state = decision.get("state") if isinstance(decision, dict) else None
        if state == "incomplete":
            return None
        if state == "unknown":
            return self._finish_outcome(False, "visual_unknown")

        from scene_demo.finish_v1 import control

        try:
            finish = control.run_finish(
                self.port, self.context, verdict, _vision.decide, self._check,
                emit=lambda row: None,
            )
        except Exception:
            self.close()
            raise
        self._finish = finish

        # run_finish may swallow exceptions; ensure cancel propagates to service.
        self.guarded_step(lambda: None)

        if isinstance(finish, dict) and finish.get("ok"):
            if self.independent_streak >= 5:
                return self._finish_outcome(True, "complete")
            return self._finish_outcome(False, "independent_finish_failed")
        reason = "independent_finish_failed"
        if isinstance(finish, dict) and finish.get("reason"):
            reason = finish["reason"]
        return self._finish_outcome(False, reason)

    def status(self):
        return {
            "phase": self.port.phase,
            "calls": self.calls,
            "prechecks": self.prechecks,
            "helper_counts": dict(self.helper_counts),
            "last_decision": self._last_decision,
            "terminal": self.terminal,
            "independent_streak": self.independent_streak,
        }

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            self.port.close()
        except Exception:
            pass
"}'
